const r = $input.first().json || {};
let o = {};
try { o = JSON.parse(icerik(r)); } catch (e) { o = {}; }
const gecerli = ['cevap', 'soru_iste', 'hata_yardimi', 'genel_yardim', 'risk', 'kapsam_disi'];
let niyet = gecerli.includes(o.niyet) ? o.niyet : (d.foto_var === 'evet' ? 'hata_yardimi' : (d.durum.bekleyen ? 'cevap' : (d.durum.hata_oturumu ? 'hata_yardimi' : 'genel_yardim')));
let risk_tipi = ['fiziksel', 'duygusal', 'uygunsuz'].includes(o.risk_tipi) ? o.risk_tipi : 'yok';
if (risk_tipi !== 'yok') niyet = 'risk';
if (niyet === 'risk' && risk_tipi === 'yok') risk_tipi = 'duygusal';
if (niyet === 'cevap' && !d.durum.bekleyen) niyet = 'genel_yardim';
if (d.foto_var === 'buyuk') niyet = 'foto_buyuk';
if (!d.profil_var) niyet = 'kimlik_hatasi';
return [{ json: { ...d, niyet, konu: String(o.konu || '').slice(0, 80), risk_tipi } }];

