return [{ json: { ...d, deger, sonuc } }];

const kopya = (x) => JSON.parse(JSON.stringify(x));
const madde = (a) => a.map((x) => '• ' + x).join('\n');

const d = $input.first().json;
const v = d.deger;
const b = d.durum.bekleyen;
const s = kopya(d.durum);
const konu = b.konu || d.konu || 'genel';
const eski = typeof s.ustalik[konu] === 'number' ? s.ustalik[konu] : 0.5;
s.ustalik[konu] = Math.round((0.7 * eski + 0.3 * 1) * 100) / 100;
s.seri = (s.seri || 0) + 1; s.toplam = (s.toplam || 0) + 1; s.dogru = (s.dogru || 0) + 1;
