if (s.ardisik_dogru >= 2 && (s.zorluk || 2) < 3) { s.zorluk = (s.zorluk || 2) + 1; s.ardisik_dogru = 0; }
s.bekleyen = null; s.son_konu = konu;
const hedefte = s.ustalik[konu] >= Number(d.hedef_ustalik);
const p = ['✅ **Doğru, tebrikler!**'];
if (v.dogru_kisimlar.length) p.push(madde(v.dogru_kisimlar));
