p.push(hedefte ? '🎯 Bu konuda hedefin üzerindesin! **"ileri düzey soru"** ya da yeni bir konu yazabilirsin.' : 'Devam için **"yeni soru"** yaz ya da başka bir konu söyle.');
return [{ json: { ...d, output: p.join('\n\n'), yeni_durum: s, log: { niyet: 'cevap', konu, sonuc: 'dogru', puan: v.puan, ipucu_seviye: b.ipucu_seviye || 0 } } }];

