const ay = $('Ayarlar').first().json;
const satirlar = $input.all().map((x) => x.json).filter((x) => x && x.kod);
const simdi = Date.now();
const gunMs = 86400000;
const esikGun = Number(ay.proaktif_gun) || 5;
const test = String(ay.proaktif_test).toLowerCase() === 'evet';
const hedef = Number(ay.hedef_ustalik) || 0.8;
const ufuk = 7; // bir sonraki zamanlayıcı çalışmasına kadar gün
// Ustalık arttıkça unutmanın yavaşladığını varsayan yaklaşık bir planlama eğrisi.
const hatirlama = (u, gun) => Number(u) * Math.exp(-gun / (5 + 20 * Number(u)));
const cikti = [];
const ozet = { toplam: satirlar.length, aktif: 0, sessiz: [], dikkat: [], konular: {}, bekleyen_soru: 0 };
for (const s of satirlar) {
  let d = {};
  try { d = s.durum ? JSON.parse(s.durum) : {}; } catch (e) { d = {}; }
  const son = s.son_etkilesim ? Date.parse(s.son_etkilesim) : NaN;
  const gun = isFinite(son) ? Math.max(0, Math.floor((simdi - son) / gunMs)) : 999;
  const ust = d.ustalik || {};
  const hatalar = d.hata_sayac || {};
  const konular = Object.keys(ust);
  const ort = konular.length ? konular.reduce((t, k) => t + Number(ust[k] || 0), 0) / konular.length : null;
  const dogruluk = (d.toplam || 0) >= 3 ? (d.dogru || 0) / d.toplam : null;
  const enCok = Object.entries(hatalar).sort((a, b) => Number(b[1]) - Number(a[1]))[0];
  const bekleyenVar = !!(d.bekleyen && String(d.bekleyen.soru || '').trim());
  Object.entries(hatalar).forEach(([k, v]) => { ozet.konular[k] = (ozet.konular[k] || 0) + Number(v || 0); });
  if (gun <= 7) ozet.aktif++;
  if (gun >= esikGun) ozet.sessiz.push(s.kod + ' (' + (gun === 999 ? 'hiç giriş yok' : gun + ' gün') + ')');

  // 1) Risk skoru (0-100): öğrencinin önümüzdeki dönemde takılma/bırakma riski
  let risk = 0; const nedenler = [];
  if (gun === 999) { risk += 40; nedenler.push('hiç giriş yok'); }
  else { risk += Math.min(40, gun * 5); if (gun >= 3) nedenler.push(gun + ' gündür etkileşim yok'); }
  if (dogruluk !== null) { risk += Math.round((1 - dogruluk) * 25); if (dogruluk < 0.5) nedenler.push('doğruluk %' + Math.round(dogruluk * 100)); }
  if ((d.ardisik_yanlis || 0) >= 2) { risk += 15; nedenler.push('üst üste yanlış'); }
  if (enCok && Number(enCok[1]) >= 3) { risk += 15; nedenler.push(enCok[0] + ' hatası x' + enCok[1]); }
  if (ort !== null && ort < 0.5) { risk += 15; nedenler.push('düşük ustalık'); }
  risk = Math.max(0, Math.min(100, risk));
  const seviye = risk >= 60 ? 'yüksek' : (risk >= 30 ? 'orta' : 'düşük');

  // 2) Unutma tahmini: bir sonraki çalışmada hedefin %70'inin altına düşecek konu
  let unutulacak = null;
  for (const k of konular) {
    const u = Number(ust[k]);
    if (!Number.isFinite(u)) continue;
    const t = hatirlama(u, (gun === 999 ? 0 : gun) + ufuk);
    if (t < hedef * 0.7 && (!unutulacak || t < unutulacak[1])) unutulacak = [k, t];
  }
  const zayifEn = Object.entries(ust).sort((a, b) => Number(a[1]) - Number(b[1]))[0];
  const zayif = unutulacak ? unutulacak[0] : (zayifEn ? zayifEn[0] : '');

  if (seviye !== 'düşük' && gun !== 999) {
    ozet.dikkat.push(s.kod + ': risk ' + risk + '/100 (' + seviye + ')' + (nedenler.length ? ' — ' + nedenler.join(', ') : '') + (unutulacak ? ' | haftaya unutulma tahmini: ' + unutulacak[0] : ''));
  }

  // Bekleyen soruyu ezmemek ve yanıt gelmeden yeni bir hatırlatma göndermemek için dur.
  if (bekleyenVar) {
    ozet.bekleyen_soru++;
    continue;
  }

  // 3) Karar: ne zaman girişim yapılsın?
  let neden = '';
  if (test) neden = 'test';
  else if (gun >= esikGun) neden = 'sessiz';
  else if (seviye === 'yüksek' || unutulacak) neden = 'tekrar';
  if (neden) {
    cikti.push({ json: { tur: 'ogrenci', kod: s.kod, ad_kod: s.ad_kod || '', kademe: s.kademe || 'lise', sinif: s.sinif || '', eposta: s.eposta || '', neden, gun, risk_skoru: risk, risk_seviye: seviye, zayif_konu: zayif, ustalik: ust, hata_sayac: hatalar, durum: d, zorluk: d.zorluk || 2, son_konu: d.son_konu || '', son_sorular: d.son_sorular || [] } });
  }
}
// En riskli öğrenci önce işlensin
